// Lucide icons (ISC, site/src/icons/lucide/LICENSE) as plain data for React: [tag, attrs][] per icon.
// Rendered with createElement, never innerHTML (security review 2026-10-13). Same SVG set as the site.
// Output: src/generated/icons.ts (generated, git-ignored, do not edit). Dependency-free.
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const srcDir = resolve(here, "../../site/src/icons/lucide");
const outFile = resolve(here, "../src/generated/icons.ts");
const ALLOWED = new Set(["path", "circle", "rect", "line", "polyline", "polygon", "ellipse"]);
const ATTRS = new Set([
  "d",
  "cx",
  "cy",
  "r",
  "rx",
  "ry",
  "x",
  "y",
  "x1",
  "x2",
  "y1",
  "y2",
  "width",
  "height",
  "points",
]);

export function parseIcon(svg) {
  const body = svg.replace(/^[\s\S]*?<svg[^>]*>/, "").replace(/<\/svg>\s*$/, "");
  const out = [];
  for (const [, tag, attrText] of body.matchAll(/<([a-z]+)\s([^>]*?)\/?>/g)) {
    if (!ALLOWED.has(tag)) throw new Error(`unexpected <${tag}> in icon`);
    const attrs = {};
    for (const [, k, v] of attrText.matchAll(/([a-z0-9-]+)="([^"]*)"/g)) {
      const ok = ATTRS.has(k) || (k === "fill" && (v === "currentColor" || v === "none"));
      if (!ok) throw new Error(`unexpected attribute ${k}="${v}" on <${tag}>`);
      attrs[k] = v;
    }
    out.push([tag, attrs]);
  }
  return out;
}

function main() {
  const icons = {};
  for (const f of readdirSync(srcDir)
    .filter((n) => n.endsWith(".svg"))
    .sort()) {
    icons[f.replace(/\.svg$/, "")] = parseIcon(readFileSync(resolve(srcDir, f), "utf8"));
  }
  const ts =
    "// GENERATED by scripts/build-icons.mjs from site/src/icons/lucide (Lucide, ISC) — do not edit.\n" +
    "export type IconNode = [string, Record<string, string>];\n" +
    `export const ICONS: Record<string, IconNode[]> = ${JSON.stringify(icons)};\n`;
  mkdirSync(dirname(outFile), { recursive: true });
  writeFileSync(outFile, ts);
  console.log(`icons: ${Object.keys(icons).length} → ${outFile}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
